{"code":"# Dump lesson content wrapper structure
info = js("""(() => {
  const w = document.querySelector('#lesson-content-wrapper') || document.querySelector('.lesson');
  const tree = [];
  function walk(el, depth) {
    if (depth > 3) return;
    for (const c of el.children) {
      tree.push('  '.repeat(depth) + c.tagName + (c.id ? '#'+c.id : '') + (c.className && typeof c.className === 'string' ? '.' + c.className.trim().split(/\\s+/).slice(0,3).join('.') : ''));
      if (depth < 2) walk(c, depth+1);
    }
  }
  walk(w, 0);
  return tree.join('\\n');
})()""")
print(info[:3000])"}

